import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '임직원';
const STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];
const ACTIONS = ['승인', '보류', '반려'];
// 가정: 보류된 문서도 해당 결재자가 다시 처리할 수 있다 (보류 후 재처리 규칙이 문서에 없음)
const PROCESSABLE = ['결재대기', '진행중', '보류'];
// 가정: 회수는 아무 결재자도 처리하지 않은 결재대기·진행중 문서만 가능하다
const WITHDRAWABLE = ['결재대기', '진행중'];
const NOT_FOUND = '문서를 찾을 수 없습니다.';

// 본인 권한 범위: 기안자이거나 결재선에 포함된 문서
const SCOPE = `(d.drafter_id = CAST(:userId AS bigint) OR EXISTS (SELECT 1 FROM approval_line sl WHERE sl.approval_document_id = d.approval_document_id AND sl.approver_id = CAST(:userId AS bigint)))`;

function idOf(v: unknown): string {
  const s = String(v ?? '');
  if (!/^\d+$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', 'ID 형식이 올바르지 않습니다.');
  }
  return s;
}

function pagingOf(q: Record<string, unknown>): { page: number; size: number } {
  const rawPage = q['page'];
  const rawSize = q['size'];
  const page = rawPage === undefined || rawPage === '' ? 0 : Number(rawPage);
  const size = rawSize === undefined || rawSize === '' ? 20 : Number(rawSize);
  if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', 'page 또는 size 값이 올바르지 않습니다.');
  }
  return { page, size: Math.min(size, 200) };
}

function dateOf(v: unknown): string {
  const s = String(v);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '날짜 형식이 올바르지 않습니다.');
  }
  return s;
}

function has(v: unknown): boolean {
  return v !== undefined && v !== null && String(v) !== '';
}

@Controller('api/v1')
export class FnSfr029105X949722Controller {
  @Post('/approval-documents/:approvalDocumentId/process')
  @HttpCode(200)
  async processApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const id = idOf(req.params['approvalDocumentId']);
    const actionType = String(data['actionType'] ?? '');
    if (!ACTIONS.includes(actionType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '처리 유형을 선택해 주세요.');
    }
    const opinion = has(data['opinion']) ? String(data['opinion']).trim() : '';
    if (actionType === '반려' && opinion === '') {
      throw new ApiError(422, 'REJECT_OPINION_REQUIRED', '반려 시에는 결재 의견을 입력해 주세요.');
    }
    return transaction(async (db) => {
      const docs = await db.query(
        `SELECT d.approval_status AS "approvalStatus" FROM approval_document d WHERE d.approval_document_id = CAST(:id AS bigint) AND ${SCOPE} FOR UPDATE OF d`,
        { id, userId: user.id },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', NOT_FOUND);
      }
      const lines = await db.query(
        `SELECT approval_line_id AS "lineId", approver_id AS "approverId" FROM approval_line WHERE approval_document_id = CAST(:id AS bigint) AND (action_type IS NULL OR action_type = '보류') ORDER BY line_group, sequence_no`,
        { id },
      );
      const turn = lines[0];
      if (!PROCESSABLE.includes(String(docs[0]['approvalStatus'])) || !turn || String(turn['approverId']) !== String(user.id)) {
        throw new ApiError(409, 'NOT_APPROVER_TURN', '본인 결재 차례가 아닌 문서입니다.');
      }
      await db.execute(
        `UPDATE approval_line SET action_type = :actionType, opinion = :opinion, processed_at = now(), updated_at = now() WHERE approval_line_id = CAST(:lineId AS bigint)`,
        { actionType, opinion: opinion === '' ? null : opinion, lineId: String(turn['lineId']) },
      );
      let status = '진행중';
      if (actionType === '반려') {
        status = '반려';
      } else if (actionType === '보류') {
        status = '보류';
      } else if (lines.length === 1) {
        status = '완료';
      }
      if (status === '완료') {
        await db.execute(
          `UPDATE approval_document SET approval_status = '완료', completed_at = now(), updated_at = now() WHERE approval_document_id = CAST(:id AS bigint)`,
          { id },
        );
      } else {
        await db.execute(
          `UPDATE approval_document SET approval_status = :status, updated_at = now() WHERE approval_document_id = CAST(:id AS bigint)`,
          { status, id },
        );
      }
      return { approvalStatus: status };
    });
  }

  @Post('/approval-documents/:approvalDocumentId/withdraw')
  @HttpCode(200)
  async withdrawApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['approvalDocumentId']);
    return transaction(async (db) => {
      const docs = await db.query(
        `SELECT approval_status AS "approvalStatus" FROM approval_document WHERE approval_document_id = CAST(:id AS bigint) AND drafter_id = CAST(:userId AS bigint) FOR UPDATE`,
        { id, userId: user.id },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', NOT_FOUND);
      }
      const done = await db.query(
        `SELECT COUNT(*) AS "cnt" FROM approval_line WHERE approval_document_id = CAST(:id AS bigint) AND action_type IS NOT NULL`,
        { id },
      );
      if (!WITHDRAWABLE.includes(String(docs[0]['approvalStatus'])) || Number(done[0]['cnt']) > 0) {
        throw new ApiError(409, 'WITHDRAW_NOT_ALLOWED', '다음 결재자가 이미 처리한 문서는 회수할 수 없습니다.');
      }
      await db.execute(
        `UPDATE approval_document SET approval_status = '회수', updated_at = now() WHERE approval_document_id = CAST(:id AS bigint)`,
        { id },
      );
      return { approvalStatus: '회수' };
    });
  }

  @Get('/approval-documents')
  async listApprovalDocuments(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = pagingOf(q);
    const where: string[] = [SCOPE];
    const params: Record<string, unknown> = { userId: user.id };
    if (has(q['approvalStatus'])) {
      const st = String(q['approvalStatus']);
      if (!STATUSES.includes(st)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '결재 진행 상태 값이 올바르지 않습니다.');
      }
      where.push('d.approval_status = :approvalStatus');
      params['approvalStatus'] = st;
    }
    if (has(q['startDate'])) {
      where.push('d.submitted_at >= CAST(:startDate AS date)');
      params['startDate'] = dateOf(q['startDate']);
    }
    if (has(q['endDate'])) {
      where.push('d.submitted_at < CAST(:endDate AS date) + 1');
      params['endDate'] = dateOf(q['endDate']);
    }
    if (has(q['drafterId'])) {
      where.push('d.drafter_id = CAST(:drafterId AS bigint)');
      params['drafterId'] = idOf(q['drafterId']);
    }
    if (String(q['scheduledOnly'] ?? '') === 'true') {
      where.push(`d.approval_status IN ('결재대기', '진행중', '보류') AND EXISTS (SELECT 1 FROM approval_line l WHERE l.approval_document_id = d.approval_document_id AND l.approver_id = CAST(:userId AS bigint) AND (l.action_type IS NULL OR l.action_type = '보류') AND NOT EXISTS (SELECT 1 FROM approval_line l2 WHERE l2.approval_document_id = l.approval_document_id AND (l2.action_type IS NULL OR l2.action_type = '보류') AND (l2.line_group, l2.sequence_no) < (l.line_group, l.sequence_no)))`);
    }
    const cond = where.join(' AND ');
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT d.approval_document_id AS "approvalDocumentId", d.document_number AS "documentNumber", d.title AS "title", d.approval_status AS "approvalStatus", d.drafter_id AS "drafterId", d.submitted_at AS "submittedAt" FROM approval_document d WHERE ${cond} ORDER BY d.approval_document_id DESC LIMIT :size OFFSET :offset`,
        { ...params, size, offset: page * size },
      );
      const cnt = await db.query(
        `SELECT COUNT(*) AS "total" FROM approval_document d WHERE ${cond}`,
        params,
      );
      return { items, page, size, total: Number(cnt[0]['total']) };
    });
  }

  @Get('/approval-documents/:approvalDocumentId')
  async getApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['approvalDocumentId']);
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT d.approval_document_id AS "approvalDocumentId", d.title AS "title", d.body AS "body", d.approval_status AS "approvalStatus" FROM approval_document d WHERE d.approval_document_id = CAST(:id AS bigint) AND ${SCOPE}`,
        { id, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', NOT_FOUND);
      }
      return rows[0];
    });
  }

  @Get('/approval-lines')
  async listApprovalLines(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    if (!has(q['approvalDocumentId'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서를 지정해 주세요.');
    }
    const id = idOf(q['approvalDocumentId']);
    const { page, size } = pagingOf(q);
    return transaction(async (db) => {
      const docs = await db.query(
        `SELECT d.approval_document_id AS "approvalDocumentId" FROM approval_document d WHERE d.approval_document_id = CAST(:id AS bigint) AND ${SCOPE}`,
        { id, userId: user.id },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', NOT_FOUND);
      }
      const items = await db.query(
        `SELECT approver_id AS "approverId", line_group AS "lineGroup", sequence_no AS "sequenceNo", action_type AS "actionType", opinion AS "opinion", processed_at AS "processedAt" FROM approval_line WHERE approval_document_id = CAST(:id AS bigint) ORDER BY line_group, sequence_no LIMIT :size OFFSET :offset`,
        { id, size, offset: page * size },
      );
      const cnt = await db.query(
        `SELECT COUNT(*) AS "total" FROM approval_line WHERE approval_document_id = CAST(:id AS bigint)`,
        { id },
      );
      return { items, page, size, total: Number(cnt[0]['total']) };
    });
  }
}

