import { useState } from 'react';
import { Badge, Band, DataTable, DateText, Drawer, Field, Filters, Form, Pager, Pairs, RefName, Select, TextInput, call, useData } from '../kit';
import type { PageProps, Row, Page } from '../kit';

const STATUS_OPTIONS: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['진행중', '진행중'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['완료', '완료'],
];

const ACTION_OPTIONS: [string, string][] = [
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
];

function Detail({ id, role, notify, canProcess, onClose, onDone }: {
  id: number;
  role: string;
  notify: (text: string) => void;
  canProcess: boolean;
  onClose: () => void;
  onDone: () => void;
}) {
  const [mode, setMode] = useState<'view' | 'process' | 'withdraw'>('view');
  const [actionType, setActionType] = useState('');
  const [opinion, setOpinion] = useState('');
  const doc = useData(() => call<Row>('GET', '/approval-documents/' + id, role), [role, id]);
  const lines = useData(() => call<Page>('GET', '/approval-lines', role, undefined, { approvalDocumentId: id, size: 200 }), [role, id]);
  const status = String(doc.data?.approvalStatus ?? '');
  const lineRows = lines.data?.items ?? [];
  const anyProcessed = lineRows.some((l) => l.actionType);
  const showProcess = canProcess && ['결재대기', '진행중', '보류'].includes(status);
  const showWithdraw = ['결재대기', '진행중'].includes(status) && !anyProcessed;

  const submitProcess = async () => {
    if (!actionType) {
      throw new Error('처리 유형을 선택해 주세요.');
    }
    if (actionType === '반려' && !opinion.trim()) {
      throw new Error('반려 시에는 결재 의견을 입력해 주세요.');
    }
    await call('POST', '/approval-documents/' + id + '/process', role, { actionType, opinion });
    notify(actionType + ' 처리했습니다.');
    onDone();
  };

  const submitWithdraw = async () => {
    await call('POST', '/approval-documents/' + id + '/withdraw', role, {});
    notify('회수했습니다.');
    onDone();
  };

  if (mode === 'process') {
    return (
      <Drawer title='결재 처리' onClose={onClose}>
        <Form onSubmit={submitProcess} submit='처리'>
          <Field label='처리 유형' required>
            <Select value={actionType} onChange={setActionType} options={ACTION_OPTIONS} />
          </Field>
          <Field label='결재 의견' wide hint='반려 시 필수'>
            <TextInput value={opinion} onChange={setOpinion} multiline />
          </Field>
        </Form>
      </Drawer>
    );
  }

  if (mode === 'withdraw') {
    return (
      <Drawer title='문서 회수' onClose={onClose}>
        <Form onSubmit={submitWithdraw} submit='회수' danger note='다음 결재자가 처리하기 전의 문서만 회수할 수 있습니다.' />
      </Drawer>
    );
  }

  return (
    <Drawer title='결재문서 상세' onClose={onClose}>
      <Pairs
        items={[
          ['문서 제목', String(doc.data?.title ?? '')],
          ['결재 진행 상태', <Badge value={doc.data?.approvalStatus} />],
          ['문서 본문', String(doc.data?.body ?? '')],
        ]}
      />
      <h2>결재선</h2>
      <DataTable
        rows={lineRows}
        empty='결재선이 없습니다.'
        columns={[
          { key: 'approverId', label: '결재자', render: (r) => <RefName table='employee' role={role} value={r.approverId} /> },
          { key: 'lineGroup', label: '결재선 구분' },
          { key: 'sequenceNo', label: '결재 순서' },
          { key: 'actionType', label: '처리 유형', render: (r) => <Badge value={r.actionType} /> },
          { key: 'opinion', label: '결재 의견' },
          { key: 'processedAt', label: '처리 일시', render: (r) => <DateText value={r.processedAt} time /> },
        ]}
      />
      <div>
        {showProcess && <button onClick={() => setMode('process')}>결재 처리</button>}
        {showWithdraw && <button onClick={() => setMode('withdraw')}>회수</button>}
      </div>
    </Drawer>
  );
}

export default function FnSfr029105X949722Page({ role, notify }: PageProps) {
  const [status, setStatus] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);

  const list = useData(
    () => call<Page>('GET', '/approval-documents', role, undefined, { ...applied, page, size: 10 }),
    [role, applied, page],
  );
  const scheduled = useData(
    () => call<Page>('GET', '/approval-documents', role, undefined, { scheduledOnly: true, size: 200 }),
    [role],
  );
  const scheduledIds = (scheduled.data?.items ?? []).map((r) => Number(r.approvalDocumentId));

  const search = () => {
    setPage(0);
    setApplied({ approvalStatus: status, startDate, endDate });
  };
  const reset = () => {
    setStatus('');
    setStartDate('');
    setEndDate('');
    setPage(0);
    setApplied({});
  };
  const done = () => {
    setSelected(null);
    list.reload();
    scheduled.reload();
  };

  return (
    <div className='bento'>
      <section className='box span-8'>
        <h2>결재 문서</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='결재 진행 상태'>
            <Select value={status} onChange={setStatus} options={STATUS_OPTIONS} placeholder='전체' />
          </Field>
          <Field label='조회 시작일'>
            <input type='date' value={startDate} onChange={(e) => setStartDate(e.target.value)} />
          </Field>
          <Field label='조회 종료일'>
            <input type='date' value={endDate} onChange={(e) => setEndDate(e.target.value)} />
          </Field>
        </Filters>
        <Band total={list.data?.total} />
        <DataTable
          rows={list.data?.items ?? []}
          onRowClick={(r) => setSelected(Number(r.approvalDocumentId))}
          empty='조회된 문서가 없습니다.'
          columns={[
            { key: 'documentNumber', label: '문서번호' },
            { key: 'title', label: '문서 제목' },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r.approvalStatus} /> },
            { key: 'drafterId', label: '기안자', render: (r) => <RefName table='employee' role={role} value={r.drafterId} /> },
            { key: 'submittedAt', label: '상신 일시', render: (r) => <DateText value={r.submittedAt} time /> },
          ]}
        />
        <Pager page={page} size={10} total={list.data?.total ?? 0} onPage={setPage} />
      </section>
      <section className='box span-4'>
        <h2>결재 예정</h2>
        <Band total={scheduled.data?.total} />
        <DataTable
          rows={scheduled.data?.items ?? []}
          onRowClick={(r) => setSelected(Number(r.approvalDocumentId))}
          empty='결재 예정 문서가 없습니다.'
          columns={[
            { key: 'title', label: '문서 제목' },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r.approvalStatus} /> },
          ]}
        />
      </section>
      {selected !== null && (
        <Detail
          key={selected}
          id={selected}
          role={role}
          notify={notify}
          canProcess={scheduledIds.includes(selected)}
          onClose={() => setSelected(null)}
          onDone={done}
        />
      )}
    </div>
  );
}
